package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

func main() {
	reader := bufio.NewReader(os.Stdin)
	var w, h int
	fmt.Fscan(reader, &w, &h)

	// Total number of ordered triples of distinct points
	// Total points N = (w+1)*(h+1)
	// Total ordered triples = N * (N-1) * (N-2)
	N := int64((w + 1) * (h + 1))
	total := N * (N - 1) % MOD * (N - 2) % MOD

	// We need to subtract the number of collinear ordered triples.
	// A line through two integer points (x1,y1), (x2,y2) contains integer points
	// spaced by (dx/g, dy/g) where dx=x2-x1, dy=y2-y1, g=gcd(dx, dy).
	// Number of integer points on segment = g + 1.
	// Number of ordered triples on this segment = (g+1)*g*(g-1).
	// We sum this over all unordered pairs of points, then divide by something? No.
	// Standard approach: Count collinear triples by considering all lines.
	// Or: Sum over all vectors (dx, dy).

	// Number of collinear ordered triples:
	// Sum over all unordered pairs of distinct points (P1, P2) of (g-1) * 6? 
	// Let's use the vector method.
	// For a vector (dx, dy) with dx >= 0, (dx, dy) != (0,0).
	// g = gcd(dx, dy).
	// Number of segments with this vector in the grid:
	// If dx > 0 and dy > 0: (w+1-dx) * (h+1-dy) * 2 (for +dy and -dy)
	// If dx > 0 and dy == 0: (w+1-dx) * (h+1)
	// If dx == 0 and dy > 0: (w+1) * (h+1-dy)
	// Each segment has g+1 points.
	// Number of ordered triples on a segment with k points is k*(k-1)*(k-2).
	// Here k = g+1.
	// So contribution per segment is (g+1)*g*(g-1).

	collinear := int64(0)

	// Precompute gcd? w,h up to 4000. O(w*h) is 16M, acceptable.
	// We can iterate dx from 0 to w, dy from 0 to h.

	gcdCache := make([][]int, w+1)
	for i := range gcdCache {
		gcdCache[i] = make([]int, h+1)
	}
	for i := 0; i <= w; i++ {
		for j := 0; j <= h; j++ {
			gcdCache[i][j] = gcd(i, j)
		}
	}

	// Case 1: dx = 0, dy > 0 (Vertical lines)
	// Vector (0, dy). g = dy.
	// Segments count: (w+1) * (h+1-dy)
	// Contribution per segment: (dy+1)*dy*(dy-1)
	for dy := 1; dy <= h; dy++ {
		g := dy
		if g < 2 {
			continue // (g+1)g(g-1) is 0 for g<2
		}
		countSeg := int64(w+1) * int64(h+1-dy)
		contrib := int64(g+1) * int64(g) * int64(g-1)
		collinear = (collinear + countSeg%MOD * contrib%MOD) % MOD
	}

	// Case 2: dx > 0, dy = 0 (Horizontal lines)
	// Vector (dx, 0). g = dx.
	// Segments count: (w+1-dx) * (h+1)
	for dx := 1; dx <= w; dx++ {
		g := dx
		if g < 2 {
			continue
		}
		countSeg := int64(w+1-dx) * int64(h+1)
		contrib := int64(g+1) * int64(g) * int64(g-1)
		collinear = (collinear + countSeg%MOD * contrib%MOD) % MOD
	}

	// Case 3: dx > 0, dy > 0 (Diagonal lines)
	// Vector (dx, dy) and (dx, -dy).
	// g = gcd(dx, dy).
	// Segments count for (dx, dy): (w+1-dx) * (h+1-dy)
	// Segments count for (dx, -dy): (w+1-dx) * (h+1-dy)
	// Total segments for this |dx|, |dy|: 2 * (w+1-dx) * (h+1-dy)
	for dx := 1; dx <= w; dx++ {
		for dy := 1; dy <= h; dy++ {
			g := gcdCache[dx][dy]
			if g < 2 {
				continue
			}
			countSeg := int64(2) * int64(w+1-dx) * int64(h+1-dy)
			contrib := int64(g+1) * int64(g) * int64(g-1)
			collinear = (collinear + countSeg%MOD * contrib%MOD) % MOD
		}
	}

	ans := (total - collinear) % MOD
	if ans < 0 {
		ans += MOD
	}
	fmt.Println(ans)
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}
